"""Offline playback of actual HistoryInstrumentTheory simulation frames."""
import json

import numpy as np


def build_history_html(runs, potential):
    density_scale = max(float(r.densities.max()) for r in runs)
    example_scale = max(float(r.example_densities.max()) for r in runs)

    def encode(values, scale):
        return np.rint(255*np.sqrt(np.clip(values/max(scale, 1e-30), 0, 1))).astype(np.uint8).tolist()

    payload = dict(densityScale=density_scale, exampleScale=example_scale,
        potential=encode(potential.V_real, max(float(potential.V_real.max()), 1e-30)),
        runs=[dict(parameters=r.parameters, times=r.times.tolist(),
            density=encode(r.densities, density_scale), examples=encode(r.example_densities, example_scale),
            diagnostics=r.diagnostics, events=r.events, records=r.records, reads=r.reads) for r in runs])
    return HTML.replace('__DATA__', json.dumps(payload, separators=(',', ':'), allow_nan=False).replace('<', '\\u003c'))


HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>History Instrument · QuantumToy</title>
<style>
:root{color-scheme:dark;--ink:#e7f3f8;--muted:#96afbd;--line:#263e4d;--teal:#58e1cc;--gold:#ffca78}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 25% 0,#142e40,transparent 65%),#08131d;color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1380px;margin:auto;padding:30px 22px 60px}h1{font-size:clamp(32px,5vw,64px);letter-spacing:-.04em;line-height:1.1;margin:20px 0}h2{font-size:13px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);margin:0 0 12px}.top{display:flex;justify-content:space-between;align-items:center;color:var(--muted);font-size:12px;letter-spacing:.08em}.intro{max-width:900px;color:#b4cbd6}.pill{color:var(--teal);padding:5px 10px;border:1px solid #37655f;border-radius:40px}button,select{font:inherit;background:#102431;color:var(--ink);border:1px solid #385567;border-radius:8px;padding:8px 12px;cursor:pointer}button:hover{border-color:var(--teal)}label{display:block;font-size:12px;color:var(--muted)}input[type=range]{width:100%;accent-color:var(--teal)}.panel{background:#0c1c28e8;border:1px solid var(--line);border-radius:16px;padding:20px;margin-top:16px}.controls{display:grid;grid-template-columns:1fr auto auto 2fr;gap:16px;align-items:end}.controls select{width:100%}.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}.two .panel{min-width:0}.field{width:100%;aspect-ratio:1.25;display:block}.chart{width:100%;height:250px;display:block}.note{font-size:12px;color:var(--muted);margin:10px 0 0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}.stat{border:1px solid var(--line);border-radius:10px;padding:12px;background:#0a1720}.stat b{display:block;font-size:25px}.stat span{font-size:11px;color:var(--muted)}.teal{color:var(--teal)}.gold{color:var(--gold)}.legend{display:flex;flex-wrap:wrap;gap:15px;font-size:12px;color:var(--muted)}.status{padding:10px 12px;border-left:3px solid var(--teal);background:#09202a;margin-top:12px}.events{max-height:230px;overflow:auto;font:12px/1.7 ui-monospace,monospace}.events p{margin:4px 0}.read-controls{display:flex;gap:12px;align-items:center;justify-content:space-between}.read-controls select{max-width:180px}.equation{color:var(--gold);font:13px ui-monospace,monospace;overflow-wrap:anywhere}#timeValue{font-variant-numeric:tabular-nums;color:var(--teal)}
@media(max-width:850px){.two{grid-template-columns:1fr}.controls{grid-template-columns:1fr auto auto}.timeline{grid-column:1/-1}.stats{grid-template-columns:1fr 1fr}}@media(max-width:480px){main{padding:18px 10px}.panel{padding:14px}.top{align-items:flex-start;gap:10px}.controls{grid-template-columns:1fr 1fr}.scenario-control,.timeline{grid-column:1/-1}button,select{font-size:12px}.read-controls{align-items:flex-start;flex-direction:column}}
</style></head><body><main>
<div class="top"><span>QUANTUMTOY / HISTORY INSTRUMENT</span><div><button id="en">EN</button> <button id="fi">FI</button></div></div>
<h1 data-text="title"></h1><p class="intro" data-text="intro"></p>
<span class="pill" data-text="candidate"></span>
<section class="panel"><div class="controls">
 <div class="scenario-control"><label for="scenario" data-text="scenario"></label><select id="scenario"></select></div>
 <button id="play"></button><button id="reset" data-text="reset"></button>
 <div class="timeline"><label for="timeline"><span data-text="time"></span> <strong id="timeValue"></strong></label><input id="timeline" type="range" min="0" max="2.6" step=".01" value="0"></div>
</div><p class="equation" id="parameters"></p><p class="note" data-text="computed"></p><div class="status" id="phase"></div></section>
<div class="two">
 <section class="panel"><h2 data-text="nullTitle"></h2><canvas id="nullField" class="field" aria-label="Null ensemble density"></canvas><p class="note" data-text="fieldLegend"></p></section>
 <section class="panel"><h2 data-text="historyTitle"></h2><canvas id="historyField" class="field" aria-label="History ensemble density"></canvas><p class="note" id="densityDifference"></p></section>
</div>
<div class="stats"><div class="stat"><b id="surviving"></b><span data-text="surviving"></span></div><div class="stat"><b id="detected"></b><span data-text="detected"></span></div><div class="stat"><b id="selected"></b><span data-text="selected"></span></div><div class="stat"><b id="escaped"></b><span data-text="escaped"></span></div></div>
<div class="two">
 <section class="panel"><div class="read-controls"><h2 data-text="exampleTitle"></h2><select id="example" aria-label="Individual preparation"></select></div><canvas id="exampleField" class="field" aria-label="Individual trajectory density"></canvas><div class="status" id="exampleState"></div><p class="note" data-text="exampleNote"></p></section>
 <section class="panel"><h2 data-text="histTitle"></h2><canvas id="histogram" class="chart" aria-label="Cumulative physical detections by y bin"></canvas><div class="legend"><span class="teal" data-text="historyCurve"></span><span class="gold" data-text="nullCurve"></span></div><p class="note" id="sampling"></p><h2 style="margin-top:24px" data-text="eventsTitle"></h2><div class="events" id="events"></div></section>
</div>
<section class="panel" id="memoryPanel"><h2 data-text="memoryTitle"></h2><p class="equation" id="memoryParameters"></p><div class="stats"><div class="stat"><b id="lastRead"></b><span data-text="lastRead"></span></div><div class="stat"><b id="logged"></b><span data-text="logged"></span></div><div class="stat"><b id="reference"></b><span data-text="reference"></span></div><div class="stat"><b id="recovered"></b><span data-text="recovered"></span></div></div><p class="note" id="readTime"></p><p class="note" data-text="memoryNote"></p></section>
<section class="panel"><p class="note" data-text="limits"></p></section>
</main><script>
const DATA=__DATA__;
const TEXT={en:{title:'Watch a history become a record.',intro:'Actual Schrödinger propagation, a one-time upper/lower measurement, and an absorbing detector. Compare an ensemble with individual quantum trajectories, then follow the delayed memory reads.',candidate:'Candidate model · simulated data',scenario:'Computed selection strength',time:'Playback time',play:'Play',pause:'Pause',reset:'Beginning',computed:'The menu selects precomputed Theory runs. Change physics or memory parameters with the runner and regenerate this file. Playback does not rerun the solver.',nullTitle:'Reference ensemble · λ = 0',historyTitle:'Selected ensemble',fieldLegend:'x →, y ↑. Grey: potential barrier. Gold: detector center. Dashed: upper/lower pointer. Both ensembles use the same colour scale.',surviving:'surviving fraction',detected:'physically detected fraction',selected:'ever selected fraction',escaped:'boundary loss fraction',exampleTitle:'One preparation',exampleNote:'Examples are selected after the run to include a detected particle when available. A live conditional wavefunction has unit norm. An absorbed trajectory is zero. The ensemble includes every preparation, including zero states. Individual and ensemble panels have separate colour scales.',histTitle:'Physical first detections · cumulative',historyCurve:'History run',nullCurve:'λ = 0 run',eventsTitle:'Simulation event log · latent history',memoryTitle:'Classical memories after acquisition',lastRead:'events at latest read',logged:'unique events in read log',reference:'events in reference bank',recovered:'unique events recovered',memoryNote:'Copies share an original detector event. Reads do not renew a memory. The read log is ideal and persistent; shared loss affects the delayed bank only. Readout settings cannot change the earlier wavefunction or absorption events.',limits:'Finite periodic lattice, idealized half-plane measurement, midpoint events and a calibrated clock. This is a candidate instrument, not experimental evidence for a new theory. Frame colours are quantized for display; numerical densities and events are saved alongside this page.',acquisition:'Acquisition: quantum state evolving',readout:'Readout: fields held at the end of acquisition; only memory readouts advance',sample:'Preparation',alive:'alive, not selected',upper:'selected upper half',lower:'selected lower half',detection:'detected',escape:'lost at boundary',selection:'selection',emptyEvents:'No event yet.',difference:'Displayed density L1 difference',waiting:'Waiting for the first read.',read:'Read',records:'original records',dark:'dark records',uncertainty:'Approximate binomial standard error of detected fraction',shotCount:'preparations',memRef:'reference copies',memDelayed:'delayed copies',memReads:'reads',spacing:'spacing',loss:'copy loss',independent:'independent',shared:'shared',eta:'read success',keep:'keep',fade:'fade',refReliability:'reference reliability'},
fi:{title:'Katso historian muuttuvan tietueeksi.',intro:'Laskettu Schrödinger-eteneminen, kertaluonteinen puoliskon valinta ja absorboiva detektori. Vertaa keskimääräistä jakaumaa yksittäisiin kvanttitoteutumiin ja seuraa sitten muistien viivästettyjä lukuja.',candidate:'Ehdokasmalli · simuloitua dataa',scenario:'Laskettu valintavoimakkuus',time:'Toistoaika',play:'Toista',pause:'Pysäytä',reset:'Alkuun',computed:'Valikossa ovat etukäteen lasketut Theory-ajot. Fysiikan ja muistien parametreja muutetaan ajokomennolla ja sivu luodaan uudelleen. Toisto ei laske mallia uudelleen.',nullTitle:'Vertailujoukko · λ = 0',historyTitle:'Valitun ajon keskimääräinen jakauma',fieldLegend:'x →, y ↑. Harmaa: potentiaalivalli. Keltainen: detektorin keskus. Katkoviiva: puoliskojen raja. Molemmilla joukoilla on sama väriskaala.',surviving:'jäljellä olevien osuus',detected:'fysikaalisesti havaittujen osuus',selected:'joskus valittujen osuus',escaped:'reunahäviöiden osuus',exampleTitle:'Yksi valmistus',exampleNote:'Esimerkit valitaan ajon jälkeen niin, että mukana on havaittu hiukkanen, jos sellainen löytyi. Elävän ehdollisen aaltofunktion normi on yksi. Absorboitunut toteutuma on nolla. Keskiarvo sisältää kaikki valmistukset, myös nollatilat. Yksittäisellä ja keskimääräisellä jakaumalla on eri väriskaalat.',histTitle:'Fysikaaliset ensiosumat · kertymä',historyCurve:'Historia-ajo',nullCurve:'λ = 0 -ajo',eventsTitle:'Simulaation tapahtumaloki · piilevä historia',memoryTitle:'Klassiset muistit mittausikkunan jälkeen',lastRead:'tapahtumia viimeisessä luvussa',logged:'eri tapahtumia lukulokissa',reference:'tapahtumia vertailumuisteissa',recovered:'eri tapahtumia talteen',memoryNote:'Kopiot jakavat saman alkuperäisen detektoritapahtuman. Luku ei virkistä muistia. Lukuloki on ihanteellinen ja pysyvä; yhteinen häviäminen koskee vain viivästettyjä muisteja. Lukuasetukset eivät muuta aiempaa aaltofunktiota tai absorptioita.',limits:'Äärellinen periodinen ruudukko, idealisoitu puoliskon mittaus, aika-askeleiden keskipisteisiin sijoitetut tapahtumat ja kalibroitu kello. Kyseessä on ehdokasmalli, ei kokeellinen todiste uudesta teoriasta. Väridata on kvantisoitu näyttöä varten; numeeriset tiheydet ja tapahtumat tallennetaan sivun rinnalle.',acquisition:'Mittausikkuna: kvanttitila kehittyy',readout:'Lukuvaihe: kentät näyttävät mittausikkunan lopun tilaa; vain muistien luvut etenevät',sample:'Valmistus',alive:'elossa, ei valintaa',upper:'ylempi puolisko valittu',lower:'alempi puolisko valittu',detection:'havaittu',escape:'hävinnyt reunaan',selection:'valinta',emptyEvents:'Ei tapahtumia vielä.',difference:'Näytettyjen tiheyksien L1-ero',waiting:'Odotetaan ensimmäistä lukua.',read:'Luku',records:'alkuperäisiä tietueita',dark:'pimeitä tietueita',uncertainty:'Havaittujen osuuden likimääräinen binomikeskivirhe',shotCount:'valmistusta',memRef:'vertailukopioita',memDelayed:'viivästettyjä kopioita',memReads:'lukukertoja',spacing:'lukuväli',loss:'kopioiden häviäminen',independent:'itsenäinen',shared:'yhteinen',eta:'luvun onnistuminen',keep:'säilytys',fade:'häviämisaika',refReliability:'vertailukopion luotettavuus'}};
let lang='en',caseIndex=Math.min(1,DATA.runs.length-1),time=0,playing=false,lastFrame=0;
const $=id=>document.getElementById(id),t=key=>TEXT[lang][key];
const run=()=>DATA.runs[caseIndex], baseline=()=>DATA.runs[0];
function frameIndex(r){let k=0;while(k+1<r.times.length&&r.times[k+1]<=time+1e-10)k++;return k}
function setup(id){const canvas=$(id),box=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;canvas.width=Math.round(box.width*ratio);canvas.height=Math.round(box.height*ratio);const c=canvas.getContext('2d');c.scale(ratio,ratio);return {c,w:box.width,h:box.height}}
function paint(id,values,p){const {c,w,h}=setup(id),ny=values.length,nx=values[0].length;c.fillStyle='#07151f';c.fillRect(0,0,w,h);
 for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){const v=values[y][x]/255;c.fillStyle=`hsl(${220-50*v} ${65+20*v}% ${5+70*v}%)`;c.fillRect(x*w/nx,(ny-1-y)*h/ny,Math.ceil(w/nx),Math.ceil(h/ny));if(DATA.potential[y][x]>100){c.fillStyle=`rgba(190,203,211,${DATA.potential[y][x]/255*.45})`;c.fillRect(x*w/nx,(ny-1-y)*h/ny,Math.ceil(w/nx),Math.ceil(h/ny))}}
 const [xmin,xmax,ymin,ymax]=p.extent;const dx=(p.detector_x-xmin)/(xmax-xmin)*w,py=h-(p.pointer_y-ymin)/(ymax-ymin)*h;c.strokeStyle='#ffca78';c.setLineDash([]);c.beginPath();c.moveTo(dx,0);c.lineTo(dx,h);c.stroke();c.setLineDash([5,5]);c.strokeStyle='#b3ced488';c.beginPath();c.moveTo(0,py);c.lineTo(w,py);c.stroke();c.setLineDash([]);
}
function hist(r,k){const bins=Array(r.parameters.y_bins).fill(0);for(const e of r.events)if(e.type==='detection'&&e.time<=r.times[k])bins[e.y_bin]++;return bins}
function draw(){const r=run(),p=r.parameters,b=baseline(),k=frameIndex(r),bk=frameIndex(b),end=r.times.at(-1),d=r.diagnostics[k];
 $('timeValue').textContent=time.toFixed(3)+' T₀';$('timeline').value=time;$('timeline').max=Math.max(end,r.reads.at(-1).time);$('play').textContent=t(playing?'pause':'play');$('phase').textContent=t(time>end?'readout':'acquisition');
 $('parameters').textContent=`λ=${p.selection_strength} · σT=${p.sigma_t.toFixed(3)} T₀ · c=${p.front_time.toFixed(3)} T₀ · Γ=${p.absorption_rate}/T₀ · ${p.trajectories} ${t('shotCount')} · dt=${p.dt.toFixed(4)} T₀ · seed=${p.seed}`;
 paint('nullField',b.density[bk],b.parameters);paint('historyField',r.density[k],p);
 for(const id of ['surviving','detected','selected','escaped'])$(id).textContent=(100*d[id]).toFixed(1)+' %';
 let difference=0;for(let y=0;y<p.grid[0];y++)for(let x=0;x<p.grid[1];x++)difference+=Math.abs((r.density[k][y][x]/255)**2-(b.density[bk][y][x]/255)**2)*DATA.densityScale;
 const area=(p.extent[1]-p.extent[0])*(p.extent[3]-p.extent[2])/(p.grid[0]*p.grid[1]);$('densityDifference').textContent=t('difference')+': '+(difference*area).toFixed(4);
 const exampleIndex=Number($('example').value)||0,shot=p.example_indices[exampleIndex];paint('exampleField',r.examples[k][exampleIndex],p);let status=t('alive');for(const e of r.events)if(e.trajectory===shot&&e.time<=r.times[k])status=e.type==='selection'?t(e.half):t(e.type);$('exampleState').textContent=t('sample')+' '+shot+': '+status;
 const {c,w,h}=setup('histogram'),left=38,right=w-12,top=18,bottom=h-28,values=[hist(b,bk),hist(r,k)],max=Math.max(1,...values.flat());c.clearRect(0,0,w,h);c.strokeStyle='#34515f';c.strokeRect(left,top,right-left,bottom-top);
 values.forEach((a,i)=>{c.beginPath();a.forEach((v,j)=>{const x=left+(j+.5)/a.length*(right-left),y=bottom-v/max*(bottom-top);j?c.lineTo(x,y):c.moveTo(x,y)});c.strokeStyle=i?'#58e1cc':'#ffca78';c.lineWidth=2;c.stroke()});c.fillStyle='#96afbd';c.font='12px system-ui';c.fillText(String(max),5,top+8);c.fillText('y bin →',right-60,h-7);
 $('sampling').textContent=`${t('uncertainty')}: ±${(100*Math.sqrt(d.detected*(1-d.detected)/p.trajectories)).toFixed(2)} %. N=${p.trajectories}.`;
 const events=r.events.filter(e=>e.time<=r.times[k]).slice(-8);$('events').replaceChildren();if(!events.length)$('events').textContent=t('emptyEvents');for(const e of events){const el=document.createElement('p');el.textContent=`t=${e.time.toFixed(3)} · #${e.trajectory} · ${t(e.type)}${e.half?' · '+t(e.half):' · y='+e.y.toFixed(2)}`;$('events').append(el)}
 const m=p.memory,env=p.envelope;$('memoryParameters').textContent=`${t('memRef')}: ${m.reference_copies} · ${t('memDelayed')}: ${m.delayed_copies} · ${t('memReads')}: ${m.read_count} · ${t('spacing')}: ${m.read_spacing} T₀ · ${t('loss')}: ${t(m.loss_mode)} · ${t('eta')}: ${(100*m.read_efficiency).toFixed(0)} % · ${t('refReliability')}: ${(100*m.reference_survival).toFixed(1)} % · ${t('keep')}: ${env.retention_time} T₀ · ${t('fade')}: ${env.fade_time} T₀ · β=${env.fade_power}`;
 const reads=r.reads.filter(a=>a.time<=time+1e-10),read=reads.at(-1);for(const [id,key] of [['lastRead','last'],['logged','logged'],['reference','reference'],['recovered','recovered']])$(id).textContent=read?read[key]:'—';$('readTime').textContent=read?`${t('read')} ${reads.length}/${r.reads.length} · t=${read.time.toFixed(3)} T₀ · ${r.records.length} ${t('records')} (${r.records.filter(a=>a.dark).length} ${t('dark')})`:t('waiting');
}
function exampleOptions(){const previous=Number($('example').value)||0;$('example').replaceChildren();run().parameters.example_indices.forEach((shot,i)=>{const opt=document.createElement('option');opt.value=i;opt.textContent='#'+shot;$('example').append(opt)});$('example').value=Math.min(previous,run().parameters.example_indices.length-1)}
function language(next){lang=next;document.documentElement.lang=lang;document.querySelectorAll('[data-text]').forEach(el=>el.textContent=t(el.dataset.text));$('scenario').replaceChildren();DATA.runs.forEach((r,i)=>{const opt=document.createElement('option');opt.value=i;opt.textContent='λ = '+r.parameters.selection_strength+(i===0?' · '+t('nullCurve'):'');$('scenario').append(opt)});$('scenario').value=caseIndex;draw()}
exampleOptions();
$('en').onclick=()=>language('en');$('fi').onclick=()=>language('fi');$('scenario').onchange=e=>{caseIndex=Number(e.target.value);exampleOptions();time=Math.min(time,Math.max(run().times.at(-1),run().reads.at(-1).time));draw()};$('example').onchange=draw;$('timeline').oninput=e=>{time=Number(e.target.value);playing=false;draw()};$('play').onclick=()=>{if(time>=Number($('timeline').max))time=0;playing=!playing;lastFrame=0;draw()};$('reset').onclick=()=>{time=0;playing=false;draw()};window.addEventListener('resize',draw);
function animate(now){if(playing){if(lastFrame){time=Math.min(Number($('timeline').max),time+(now-lastFrame)/4000);if(time>=Number($('timeline').max))playing=false;draw()}lastFrame=now}else lastFrame=0;requestAnimationFrame(animate)}language('en');requestAnimationFrame(animate);
</script></body></html>'''
